                """
            }
        }
        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(sanitizeOutput(workflow.out, unstableKeys:["summary"])).match() }
            )
        }
    }

    test("sarscov2 - fastq - single-end - deacon - stub") {

        options "-stub"

        when {
            workflow {
                """
                input[0] = channel.of(
                    [
                        [ id:'test', single_end:true ],
